1	// Deterministic inert type renderer. Full admission uses the original schemas.
2	// Every exported carrier name comes from the explicit selected target table.
3	const ts = require('typescript');
4	const json = JSON.stringify;
5	
6	function renderTypes(schema, selectedNames) {
7	  const definitions = schema.definitions;
8	  const selected = new Set();
9	  const scalar = {null:'null', boolean:'boolean', integer:'bigint', string:'string'};
10	  function visit(name) {
11	    if (selected.has(name)) return;
12	    if (!Object.hasOwn(definitions, name)) throw new Error('missing named schema: '+name);
13	    selected.add(name);
14	    expression(definitions[name]);
15	  }
16	  function expression(node) {
17	    if (node === true) return 'Json';
18	    if (node === false) return 'never';
19	    // Exact literals and integer unions are produced by the Python projection,
20	    // before any JS number parsing. Never reconstruct numeric literals here.
21	    if (Object.hasOwn(node, 'tsType')) return '('+node.tsType+')';
22	    const constraints = [];
23	    if (node.$ref !== undefined) {
24	      const prefix = '#/definitions/';
25	      if (typeof node.$ref !== 'string' || !node.$ref.startsWith(prefix)) throw new Error('unflattened reference');
26	      const name = node.$ref.slice(prefix.length);
27	      visit(name);
28	      constraints.push(name);
29	    }
30	    if (node.enum !== undefined) {
31	      if (node.enum.some(v=>typeof v==='number')) throw new Error('numeric enum without exact literal projection');
32	      constraints.push('('+node.enum.map(v=>json(v)).join(' | ')+')');
33	    }
34	    if (node.const !== undefined) throw new Error('const without exact literal projection');
35	    if (node.type !== undefined) {
36	      const types = Array.isArray(node.type) ? node.type : [node.type];
37	      constraints.push('('+types.map(kind=>{
38	        if (Object.hasOwn(scalar,kind)) return scalar[kind];
39	        if (kind==='array') return '('+expression(node.items === undefined ? true : node.items)+')[]';
40	        if (kind!=='object') throw new Error('unsupported carrier type: '+kind);
41	        const fields = [];
42	        const properties = node.properties || {};
43	        const required = new Set(node.required || []);
44	        for (const key of Object.keys(properties).sort()) {
45	          fields.push(json(key)+(required.has(key)?'':'?')+': '+expression(properties[key])+';');
46	        }
47	        for (const key of [...required].sort()) {
48	          if (!Object.hasOwn(properties,key)) fields.push(json(key)+': Json;');
49	        }
50	        // Pattern/extra-key restrictions remain runtime constraints. Combining
51	        // a typed index with fixed fields can wrongly narrow those fixed fields;
52	        // use Json for the index when both coexist, retaining each named field.
53	        const patterns = Object.values(node.patternProperties || {});
54	        let index;
55	        if (node.additionalProperties !== false) index = node.additionalProperties === undefined ? 'Json' : expression(node.additionalProperties);
56	        if (patterns.length) index = [index, ...patterns.map(expression)].filter(Boolean).join(' | ');
57	        if (index) fields.push('[key: string]: '+(fields.length?'Json | undefined':index)+';');
58	        return '{'+fields.join('\n')+'}';
59	      }).join(' | ')+')');
60	    }
61	    for (const keyword of ['allOf','anyOf','oneOf']) {
62	      if (node[keyword] !== undefined) {
63	        const parts = node[keyword].map(expression);
64	        constraints.push('('+parts.join(keyword==='allOf'?' & ':' | ')+')');
65	      }
66	    }
67	    // Implicit-type constraint nodes (contains/pattern/if/not/required, etc.)
68	    // may also admit values of other JSON types. They cannot narrow the inert
69	    // type by inference. Explicit type/ref/applicator constraints above suffice.
70	    return constraints.length ? constraints.join(' & ') : 'Json';
71	  }
72	  for (const name of selectedNames) visit(name);
73	  const names = [...selected].sort();
74	  const source = names.map(name=>'export type '+name+' = '+expression(definitions[name])+';').join('\n');
75	  if (selected.size !== names.length) throw new Error('late reference discovery');
76	  const ast = ts.createSourceFile('carriers.ts', source, ts.ScriptTarget.ES2022, true, ts.ScriptKind.TS);
77	  if (ast.parseDiagnostics.length) throw new Error('generated type syntax refused');
78	  let numberTypes = 0, anyTypes = 0;
79	  function audit(node) {
80	    if (node.kind === ts.SyntaxKind.NumberKeyword) numberTypes++;
81	    if (node.kind === ts.SyntaxKind.AnyKeyword) anyTypes++;
82	    ts.forEachChild(node, audit);
83	  }
84	  audit(ast);
85	  if (numberTypes || anyTypes) throw new Error('inexact numeric or any carrier type');
86	  const exports = ast.statements.map(item=>{
87	    if (!ts.isTypeAliasDeclaration(item) || !item.modifiers?.some(m=>m.kind===ts.SyntaxKind.ExportKeyword)) throw new Error('unexpected generated declaration');
88	    return item.name.text;
89	  });
90	  if (json(exports)!==json(names)) throw new Error('carrier export set differs from selected name table');
91	  const text = ts.createPrinter({newLine:ts.NewLineKind.LineFeed}).printFile(ast);
92	  return {text, names, numberTypes, anyTypes};
93	}
94	module.exports = {renderTypes};
