2	use std::{collections::BTreeMap, env, fs, path::PathBuf};
3	use syn::{visit::Visit, visit_mut::VisitMut, Item};
4	
5	fn main() {
6	    let root = PathBuf::from(env::args().nth(1).expect("trial root"));
7	    let output = PathBuf::from(env::args().nth(2).expect("fresh output root"));
8	    let owners: serde_json::Value = serde_json::from_slice(&fs::read(root.join("owners.json")).unwrap()).unwrap();
9	    let owners: Vec<_> = owners.as_array().unwrap().iter().map(|row|
10	        (row["namespace"].as_str().unwrap().to_owned(), row["module"].as_str().unwrap().to_owned())).collect();
11	    let schema = serde_json::from_slice(&fs::read(root.join("rust-projection.json")).unwrap()).unwrap();
12	    let mut settings = typify::TypeSpaceSettings::default();
13	    settings.with_map_type(typify::MapType::new("::std::collections::BTreeMap"));
14	    settings.with_conversion(serde_json::from_value(serde_json::json!({"type":"integer"})).unwrap(), "ExactInteger", [typify::TypeSpaceImpl::Display].into_iter());
15	    let mut types = typify::TypeSpace::new(&settings);
16	    types.add_root_schema(schema).expect("schema generation");
17	    let mut parsed: syn::File = syn::parse2(types.to_stream()).expect("generated Rust syntax");
18	    PreservePresence.visit_file_mut(&mut parsed);
19	    let mut groups: BTreeMap<&str, Vec<Item>> = ["evidence", "identity", "invocation", "output", "protocol"].map(|name|(name, vec![])).into();
20	    for mut item in parsed.items {
21	        if let Item::Enum(value) = &item { assert!(!value.variants.is_empty(), "uninhabited generated enum {}", value.ident); }
22	        let name = match &item {
23	            Item::Struct(x) => x.ident.to_string(),
24	            Item::Enum(x) => x.ident.to_string(),
25	            Item::Type(x) => x.ident.to_string(),
26	            Item::Impl(x) => {
27	                // Normally the self type owns the implementation. For foreign
28	                // targets such as From<OwnedType> for String, the sole local
29	                // generated type in the trait arguments owns it instead.
30	                let mut ids = Names(vec![]);
31	                ids.visit_type(&x.self_ty);
32	                if !ids.0.iter().any(|id| owners.iter().any(|(prefix,_)|id.starts_with(prefix))) {
33	                    if let Some((_, path, _)) = &x.trait_ { ids.visit_path(path); }
34	                }
35	                ids.0.into_iter().find(|id| owners.iter().any(|(prefix,_)|id.starts_with(prefix))).expect("impl owner")
36	            }
37	            Item::Mod(x) => x.ident.to_string(),
38	            _ => panic!("unclassified generated item"),
39	        };
40	        let owner = if name == "error" || name == "defaults" {
41	            if let Item::Mod(module) = &mut item {
42	                module.vis = syn::parse_quote!(pub(crate));
43	                if name == "defaults" {
44	                    if let Some((_, items)) = &mut module.content {
45	                        for child in items { if let Item::Fn(f) = child { f.vis = syn::parse_quote!(pub(crate)); } }
46	                    }
47	                }
48	            }
49	            "evidence"
50	        } else {
51	            let matched: Vec<_> = owners.iter().filter(|(prefix,_)|name.starts_with(prefix)).collect();
52	            assert_eq!(matched.len(), 1, "unique owner of {name}");
53	            matched[0].1.as_str()
54	        };
55	        groups.get_mut(owner).unwrap().push(item);
56	    }
57	    let dir = output.join("crates/contracts/src/generated");
58	    fs::create_dir_all(&dir).unwrap();
59	    let header = "// Generated trial: named28 profile, typify0.8.0; inert carriers only.\n";
60	    for (name, items) in &groups {
61	        let mut text = header.to_owned();
62	        text.push_str("#![allow(unused_imports)]\n");
63	        for sibling in groups.keys().filter(|s|*s != name) {
64	            text.push_str(&format!("use super::{sibling}::*;\n"));
65	        }
66	        if *name != "evidence" { text.push_str("use super::evidence::error;\n"); }
67	        if *name == "evidence" { text.push_str(include_str!("presence.rs")); text.push_str(include_str!("integers.rs")); }
68	        for item in items { text.push_str(&item.to_token_stream().to_string()); text.push('\n'); }
69	        fs::write(dir.join(format!("{name}.rs")), text).unwrap();
70	    }
71	    let mut index = header.to_owned();
72	    for name in groups.keys() { index.push_str(&format!("pub mod {name};\n")); }
73	    fs::write(dir.join("mod.rs"), index).unwrap();
74	    println!("generated six Rust files");
75	}
