77	struct PreservePresence;
78	impl VisitMut for PreservePresence {
79	    fn visit_field_mut(&mut self, field: &mut syn::Field) {
80	        let mut optional = false;
81	        let mut kept = vec![];
82	        let mut attrs = vec![];
83	        for attr in &field.attrs {
84	            if attr.path().is_ident("serde") {
85	                let values = attr.parse_args_with(syn::punctuated::Punctuated::<syn::Meta, syn::Token![,]>::parse_terminated).unwrap();
86	                for value in values {
87	                    if value.path().is_ident("default") || value.path().is_ident("skip_serializing_if") {
88	                        optional = true;
89	                    } else { kept.push(value); }
90	                }
91	            } else { attrs.push(attr.clone()); }
92	        }
93	        if optional {
94	            let inner = &field.ty;
95	            field.ty = syn::parse_quote!(FieldPresence<#inner>);
96	            kept.push(syn::parse_quote!(default));
97	            kept.push(syn::parse_quote!(skip_serializing_if = "FieldPresence::is_missing"));
98	        }
99	        if !kept.is_empty() { attrs.push(syn::parse_quote!(#[serde(#(#kept),*)])); }
100	        field.attrs = attrs;
101	    }
102	}
103	
104	struct Names(Vec<String>);
105	impl<'ast> Visit<'ast> for Names {
106	    fn visit_type_path(&mut self, node: &'ast syn::TypePath) {
107	        if let Some(segment) = node.path.segments.last() { self.0.push(segment.ident.to_string()); }
108	        syn::visit::visit_type_path(self, node);
109	    }
110	    fn visit_path(&mut self, node: &'ast syn::Path) {
111	        for segment in &node.segments { self.0.push(segment.ident.to_string()); }
112	        syn::visit::visit_path(self, node);
113	    }
114	}
